import{_ as e,o as a,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-10-07","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-10-07","date":"2021-10-07T00:00:00.000Z","updated":"2021-10-08T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可扩展性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","CephFS","RBD","RADOS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-10-07.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-10-07.md","lastUpdated":1780459816000}'),t={name:"posts/2021/Ceph_Crimson_SeaStore_2021-10-07.md"};function r(n,l,h,s,u,d){return a(),i("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><ul><li>日期：未提供具体日期</li><li>时间：未提供具体时间</li></ul><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>主持人：未明确</li><li>参会人员：Schwein、Barth、Greg、Doodle、Chen May等</li></ul><h4 id="主要议题及讨论内容" tabindex="-1">主要议题及讨论内容 <a class="header-anchor" href="#主要议题及讨论内容" aria-label="Permalink to &quot;主要议题及讨论内容&quot;">​</a></h4><ol><li><p><strong>Schwein的设备PR审查</strong></p><ul><li>主持人正在审查Schwein提交的设备PR，并推送了一些清理代码的提交。</li><li>强调了编译器的重要性，简化了复合4位28位组合的转换。</li></ul></li><li><p><strong>Barth的集群问题</strong></p><ul><li>Barth尝试使用上游构建版本17.0.0-7998启动集群，但遇到添加OSD的问题。</li><li>建议Barth创建一个详细的bug报告以便进一步调查。</li></ul></li><li><p><strong>三手的多设备PR和日志批处理PR</strong></p><ul><li>讨论了多设备PR和日志批处理PR，但发现对延迟没有改善，反而变得更糟。</li><li>建议进一步研究perf工具的使用，并验证日志批处理代码的效果。</li></ul></li><li><p><strong>C-Store在Toothology中的应用</strong></p><ul><li>强调了将C-Store OSD引入Toothology的重要性，建议开始进行相关测试。</li><li>提供了访问实验室的wiki链接以便开始相关工作。</li></ul></li><li><p><strong>Greg的工作进展</strong></p><ul><li>Greg正在研究Ciladb如何处理消息传递，以避免在多反应器工作中出现潜在问题。</li></ul></li><li><p><strong>Doodle的工作进展</strong></p><ul><li>Doodle在国庆假期期间没有太多进展，计划下周继续推进Sprite LFS GC和范围放置策略的工作。</li></ul></li><li><p><strong>Chen May的培训资源</strong></p><ul><li>提供了一些YouTube视频链接，帮助Chen May熟悉相关技术和环境。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>Barth需要创建一个详细的bug报告，以便进一步调查集群启动问题。</li><li>需要进一步研究perf工具的使用，并验证日志批处理代码的效果。</li><li>开始进行C-Store OSD在Toothology中的测试工作。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>Barth创建bug报告并提供详细步骤。</li><li>继续研究perf工具的使用，并观察磁盘统计数据以验证日志批处理代码的效果。</li><li>开始C-Store OSD在Toothology中的测试工作，并访问提供的wiki链接以获取实验室访问权限。</li></ul><h4 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h4><ul><li>会议结束时，主持人祝愿大家有一个愉快的晚上/白天，并期待下周再见。</li></ul><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to &quot;结束语&quot;">​</a></h3><p>会议结束，期待下周的进展和讨论。</p>',15)])])}const S=e(t,[["render",r]]);export{c as __pageData,S as default};
